package com.comphenix.protocol.wrappers;
import com.comphenix.protocol.events.PacketContainer;
import java.util.*;
public class WrappedAttribute { private final String key; private final double base; private final Set<WrappedAttributeModifier> modifiers; private WrappedAttribute(String k,double b,Collection<WrappedAttributeModifier> m){key=k;base=b;modifiers=new HashSet<>(m);} public String getAttributeKey(){return key;} public double getBaseValue(){return base;} public Set<WrappedAttributeModifier> getModifiers(){return Collections.unmodifiableSet(modifiers);} public static Builder newBuilder(){return new Builder();} public static class Builder { private String key;private double base;private Collection<WrappedAttributeModifier> modifiers=Collections.emptyList(); public Builder packet(PacketContainer ignored){return this;} public Builder attributeKey(String k){key=k;return this;} public Builder baseValue(double b){base=b;return this;} public Builder modifiers(Collection<WrappedAttributeModifier> m){modifiers=m;return this;} public WrappedAttribute build(){return new WrappedAttribute(key,base,modifiers);} } }
